content.query:
let timeStart = {TimeRange:start};
let timeEnd = {TimeRange:end};
let timeStep = {TimeRange:grain};
Usage
| where TimeGenerated between (timeStart .. timeEnd)
| make-series Trend = sum(Quantity) default = 0 on TimeGenerated from timeStart to timeEnd step timeStep by DataType
| extend TotalMB = array_sum(Trend)
| project DataType, TotalMB, Trend
| order by TotalMB desc

parameters.query:
let tableDetails = todynamic(base64_decode_tostring("{SelectedTableDetails:base64}"));
let cols = tableDetails.properties.schema.columns;
let reserved = dynamic(["_ResourceId","id","_SubscriptionId","TenantId","Type","UniqueId","Title","RawData","tenant","MG","ManagementGroupName","SourceSystem"]);
let base = print col = cols
    | mv-expand col
    | extend Name = tostring(col.name), Type = tostring(col.type)
    | where Name !in~ (reserved)
    | extend Suffix = extract(@'_(s|d|b|g|t)$', 1, Name)
    | extend Base = extract(@'^(.*)_(?:s|d|b|g|t)$', 1, Name)
    | extend CleanName = iif(isempty(Base), Name, Base)
    | extend MappedType = case(Suffix == "s", "string", Suffix == "d", "real", Suffix == "b", "boolean", Suffix == "g", "string", Suffix == "t", "datetime", Type);
let collisionCount = toscalar(base | summarize Cnt = count() by CleanName | where Cnt > 1 | summarize TotalCollisions = count());
let mapped = base | extend InputName = iif(collisionCount > 0, Name, CleanName);
let inputColumnsJson = toscalar(
    mapped
    | extend ColJson = strcat('{"name":"', InputName, '","type":"', MappedType, '"}')
    | summarize Json = strcat("[", strcat_array(make_list(ColJson), ","), "]")
    | project Json);
let renameText = toscalar(
    mapped
    | where InputName != Name
    | extend RenameEntry = strcat(Name, " = ", InputName)
    | summarize Txt = strcat_array(make_list(RenameEntry), ",\n    ")
    | project Txt);
let transformKql = iif(isempty(renameText), "source", strcat("source\n| project-rename\n    ", renameText));
print value = tostring(bag_pack("HasCollisions", tolower(tostring(collisionCount > 0)), "CollisionCount", tostring(collisionCount), "InputColumnsJson", inputColumnsJson, "TransformKqlText", transformKql))

